-- ----------------------------
-- Table structure for article
-- ----------------------------
DROP TABLE IF EXISTS `article`;
CREATE TABLE `article`  (
  `article_id` mediumint(8) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '文章id：[0,8388607]',
  `title` varchar(125) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '标题：[0,125]用于文章和html的title标签中',
  `type` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '0' COMMENT '文章分类：[0,1000]用来搜索指定类型的文章',
  `hits` int(10) UNSIGNED NOT NULL DEFAULT 0 COMMENT '点击数：[0,1000000000]访问这篇文章的人次',
  `praise_len` int(11) NOT NULL DEFAULT 0 COMMENT '点赞数',
  `create_time` timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) COMMENT '创建时间：',
  `update_time` timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间：',
  `source` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '来源：[0,255]文章的出处',
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '来源地址：[0,255]用于跳转到发布该文章的网站',
  `tag` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '标签：[0,255]用于标注文章所属相关内容，多个标签用空格隔开',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '正文：文章的主体内容',
  `img` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '封面图',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '文章描述',
  PRIMARY KEY (`article_id`, `title`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '文章：用于内容管理系统的文章' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of article
-- ----------------------------
INSERT INTO `article` VALUES (1, '北京牛街最红店铺，一个是电视剧里的美食，一个满是老北京记忆', '商铺', 30, 0, '2022-03-07 12:58:04', '2022-03-07 21:28:17', '', '', '', '<p>自在的孤岛，满世界乱跑，关注我带你游京城。</p><p>牛街是北京著名的美食街，以清真食品和风味为主。快过年了，牛街更是热闹非凡，除了是鼎鼎有名的美食街之外，这里也是北京人置办年货的地方。清真的牛羊肉，各式各样的糕点都是牛街的特色。</p><p>虽然来到北京好几年了，但却没想着来一趟牛街。以为这里和我们西北的清真美食街差不多，来了才发现这里虽然是保留了清真食品的主要特色，也早已融入了北京当地的生活方式。</p><p><br></p><p><img src=\"https://n.sinaimg.cn/sinakd10112/117/w576h341/20220219/4ed6-0b65fae15f91854ee7e463b810aa2d13.jpg\"></p><p>到牛街之前我也没查要去哪，本着随缘的心情随便逛逛牛街。刚进入牛街的范围，几家店铺还算清净，门前没有什么人，往前走了没多远就发现几条一字排开的长队。最长的一队就是排着这家——伊宝荷叶甄糕。</p><p>第一次了解到甄糕是在电视剧《那年花开月正圆》里面，娘娘孙俪扮演的周莹最爱吃的就是甄糕。他也确确实实是陕西的传统饮食，之后传入了京城，没想到北京人也对它钟爱有加。</p><p><br></p><p><img src=\"https://n.sinaimg.cn/sinakd10112/117/w576h341/20220219/1462-62981a34ceea0682671c4361db2d48be.jpg\"></p><p>甄糕历史悠久，也叫甑糕。甑是一种底部有小孔的容器，是我国古代一种非常古老的蒸制器皿。有陶制的、铜制的、木头制的还有铁制食物。历经民间传承，有铁甑保留至今，而用它蒸制的粘糕也别有风味。</p><p>北京牛街的伊宝荷叶甄糕是北京最火爆的甄糕店，我在附近逛了一两个小时，一直排着一二十米的长队。甄糕虽然外观看起来黑乎乎的，但是软硬适度，吃起来有劲道。厚厚的一层枣泥，覆盖着糯米和红豆，口味甜而不腻，怪不得这么多人都喜欢。这家店的甄糕是按斤卖18.8一斤。店里除了甄糕还有其他糕点，如果你想要买卖相好一点的，可以选择芸豆糕，绿豆糕和花生酥。</p><p><br></p><p><img src=\"https://n.sinaimg.cn/sinakd10112/117/w576h341/20220219/6db6-a3b409f4d34cd1b4ef468b72693b6ae4.jpg\"></p><p>紧挨着荷叶甄糕的就是这家白记年糕，照样排着大长队，一眼望不到头。如果说甄糕是关中小吃，白记就北京多了。招牌的的年糕，有江米、黄米、紫米之分。驴打滚，豌豆黄，糖火烧、盆糕，山楂糕……这些糕点都透漏着老北京的喜好。白记不只用料实在，新鲜软糯，所卖的糕点颜色也很多样，五颜六色非常贴近过年喜庆热闹的氛围。所以很多人都来大批量采购，当作年货。</p><p><br></p><p><img src=\"https://n.sinaimg.cn/sinakd10112/124/w576h348/20220219/ec5a-dc87d5cca945d5327fd90dc6de9ac77b.jpg\"></p><p>被几条长队围着的一家火锅店，也是牛街闻名的铜锅火锅店。以牛街新鲜的牛羊肉品质为保障，在北京屹立几十年，店内也是一直在等位。有个小窍门儿，火锅店的另一头是聚宝源美食城。从另一边上去貌似也有一些空位，有网友评论说在美食城区域下班后也成了火锅店食物位置，可以少排一会儿队。不过因为我觉得一个人吃火锅太凄凉没有实践，想去的小伙伴可以试试。</p><p><br></p><p><img src=\"https://n.sinaimg.cn/sinakd10112/117/w576h341/20220219/955d-a5bd8bd224875b73799bf5e198b7dd84.jpg\"></p><p>虽然现在庆丰包子的名气比较大，但是这家洪记小吃的包子绝对碾压庆丰。和马路对面的两家店一样，这里也是排着长队。包子只有牛肉大葱和羊肉大葱两种，2.5元一个。面皮松软，里面馅料足汁水多，吃一口都要流油。除了包子还有炸糕，牙签肉，熟食糖耳朵，松肉。种类比较多，而且有吃东西的地方。相比要带回家的糕点，这里可以直接开吃，是逛累了的好选择。</p><p><br></p><p><img src=\"https://n.sinaimg.cn/sinakd10112/116/w576h340/20220219/7c07-d8ee5ac80a1e570c715e1da3fbad0497.jpg\"></p>', '/api/upload/4ed6-0b65fae15f91854ee7e463b810aa2d13.jpg', '2022年03月23日 12:51 新浪网');
INSERT INTO `article` VALUES (2, '店铺生意如何做到火爆？吉铺纳来告诉你', '商铺', 748, 0, '2022-03-07 12:58:04', '2022-03-07 21:28:21', '', '', '', '<p>满大街都是餐饮店面，只有这家吉铺纳小吃店还排着长队，这家店到底是有什么魔力呢？让我们一探究竟吧。</p><p><img src=\"http://n.sinaimg.cn/sinakd20220217ac/267/w640h427/20220217/8415-f72e10b00de2128dfa508af304f52d1d.png\"></p><p><br></p><p>记者刘颜：“你好这位先生，请问一下你在这排队排了多久呢？”</p><p><strong>张先生：“差不多20分钟了吧。”</strong></p><p>记者刘颜：“为什么你愿意排队这么久？我看附近小吃店都没多少人，唯独这里怎么排满了人呢？”</p><p><strong>张先生：“还不是着这家店小吃好吃味道一绝，我也是被朋友推荐过来尝试吃过一次，吃过后就再也离不开这家店了，现在每天下班必来吉铺纳打卡。”</strong></p><p>一家生意火爆的餐饮店，最重要的还是要靠味道征服食客，酒香不怕巷子深。</p>', '/api/upload/8415-f72e10b00de2128dfa508af304f52d1d.png', '2022年03月23日 12:51 新浪网');
INSERT INTO `article` VALUES (3, '店铺生意如何做到火爆？吉铺纳来告诉你', '商铺', 573, 0, '2022-03-07 12:58:04', '2022-03-07 21:28:25', '', '', '', '<p>满大街都是餐饮店面，只有这家吉铺纳小吃店还排着长队，这家店到底是有什么魔力呢？让我们一探究竟吧。</p><p><img src=\"http://n.sinaimg.cn/sinakd20220217ac/267/w640h427/20220217/8415-f72e10b00de2128dfa508af304f52d1d.png\"></p><p><br></p><p>记者刘颜：“你好这位先生，请问一下你在这排队排了多久呢？”</p><p><strong>张先生：“差不多20分钟了吧。”</strong></p><p>记者刘颜：“为什么你愿意排队这么久？我看附近小吃店都没多少人，唯独这里怎么排满了人呢？”</p><p><strong>张先生：“还不是着这家店小吃好吃味道一绝，我也是被朋友推荐过来尝试吃过一次，吃过后就再也离不开这家店了，现在每天下班必来吉铺纳打卡。”</strong></p><p>一家生意火爆的餐饮店，最重要的还是要靠味道征服食客，酒香不怕巷子深。</p>', '/api/upload/8415-f72e10b00de2128dfa508af304f52d1d.png', '2022年03月23日 12:51 新浪网');
INSERT INTO `article` VALUES (4, '美妆店铺盈利体系的搭建', '商铺', 555, 0, '2022-03-07 12:58:04', '2022-03-07 21:28:32', '', '', '', '<p>美妆店铺的营收体系，一是销售产品的收入，要有会员积累；</p><p>二是办理护理项目的年卡会员，这样能快速回笼一部分资金；</p><p>三是顾客买套盒在店里做护理，这样能锁住顾客，增加客户的到店率；</p><p>四是一些单次或者散客的产品或服务项目的收费。</p><p>五是可以通过手机移动端销售产品或者项目。</p><p><img src=\"https://n.sinaimg.cn/sinakd10109/384/w2048h1536/20220119/dadb-7483d0fb6d72cd5a91abca90caea490d.jpg\"></p>', '/api/upload/dadb-7483d0fb6d72cd5a91abca90caea490d.jpg', '2022年03月23日 12:51 新浪网');
INSERT INTO `article` VALUES (5, '测试新闻资讯', '资讯分类', 0, 1, '2022-03-07 22:04:28', '2022-03-07 22:09:27', '', '', '', '<p>测试</p><p><img src=\"data:image/jpeg;base64,\"></p><p>测试</p><p><img src=\"data:image/jpeg;base64,\"></p>', '/api/upload/339fee7eced2c9d312924fd4ad36df7d.jpg', '');

-- ----------------------------
-- Table structure for article_type
-- ----------------------------
DROP TABLE IF EXISTS `article_type`;
CREATE TABLE `article_type`  (
  `type_id` smallint(5) UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '分类ID：[0,10000]',
  `display` smallint(4) UNSIGNED NOT NULL DEFAULT 100 COMMENT '显示顺序：[0,1000]决定分类显示的先后顺序',
  `name` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '' COMMENT '分类名称：[2,16]',
  `father_id` smallint(5) UNSIGNED NOT NULL DEFAULT 0 COMMENT '上级分类ID：[0,32767]',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '描述：[0,255]描述该分类的作用',
  `icon` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '分类图标：',
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '外链地址：[0,255]如果该分类是跳转到其他网站的情况下，就在该URL上设置',
  `create_time` timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) COMMENT '创建时间：',
  `update_time` timestamp(0) NOT NULL DEFAULT CURRENT_TIMESTAMP(0) ON UPDATE CURRENT_TIMESTAMP(0) COMMENT '更新时间：',
  PRIMARY KEY (`type_id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 3 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '文章频道：用于汇总浏览文章，在不同频道下展示不同文章。' ROW_FORMAT = Dynamic;

